private.reference_solution:
var words = new SortedSet<string>(StringComparer.Ordinal);
foreach (var raw in Console.In.ReadToEnd().Replace("\r\n", "\n").Split('\n'))
{
    if (raw.Length == 0) continue;
    words.Add(raw);
}
File.WriteAllLines("words.txt", words);
var stored = File.ReadAllLines("words.txt");
Console.WriteLine($"count={stored.Length}");
if (stored.Length > 0)
{
    Console.WriteLine($"first={stored[0]}");
    Console.WriteLine($"last={stored[^1]}");
}
